begin;
create schema circuito;
revoke all on schema circuito from public,anon,authenticated;
create table public.cic_cafes(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,address text,hours text,combo text,description text,photo text,logo text,instagram text,lat double precision check(lat between -90 and 90),lng double precision check(lng between -180 and 180),active boolean not null default true);
create table circuito.placas(cafe uuid primary key references public.cic_cafes,token uuid unique not null default gen_random_uuid());
create function circuito.nova() returns trigger language plpgsql security definer set search_path='' as $$begin insert into circuito.placas(cafe) values(new.id);return new;end$$;
create trigger nova after insert on public.cic_cafes for each row execute function circuito.nova();
create table public.cic_perfis(id uuid primary key default auth.uid() references auth.users on delete cascade,cidade text not null check(length(trim(cidade)) between 2 and 100),uf text not null check(uf ~ '^[A-Z]{2}$'),aceite text not null check(aceite='1.2'),desde timestamptz not null default now(),novidades boolean not null default false);
create table public.cic_visitas(pessoa uuid references public.cic_perfis on delete cascade,cafe uuid references public.cic_cafes,instante timestamptz not null default now(),metros integer not null,valida boolean not null default true,primary key(pessoa,cafe));
create table circuito.tentativas(pessoa uuid references auth.users on delete cascade,instante timestamptz default now());
create index on circuito.tentativas(pessoa,instante);
alter table public.cic_cafes enable row level security;
alter table public.cic_perfis enable row level security;
alter table public.cic_visitas enable row level security;
revoke all on public.cic_cafes,public.cic_perfis,public.cic_visitas from public,anon,authenticated;
grant select on public.cic_cafes to anon,authenticated;
create policy catalogo on public.cic_cafes for select using(active);
grant select,insert(id,cidade,uf,aceite,novidades),update(cidade,uf,novidades) on public.cic_perfis to authenticated;
create policy perfil on public.cic_perfis to authenticated using(id=auth.uid()) with check(id=auth.uid());
grant select on public.cic_visitas to authenticated;
create policy passaporte on public.cic_visitas for select using(pessoa=auth.uid());
create function public.cic_checkin(placa uuid,latitude double precision,longitude double precision,precisao double precision) returns text language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); c public.cic_cafes; d double precision;
begin
if u is null or not exists(select from public.cic_perfis where id=u) then return 'Complete seu cadastro.';end if;
if (now() at time zone 'America/Sao_Paulo')::date not between date '2026-11-16' and date '2027-02-10' then return 'Campanha encerrada ou ainda não iniciada.';end if;
perform pg_advisory_xact_lock(hashtextextended(u::text,0));
delete from circuito.tentativas where pessoa=u and instante<=now()-interval '1 hour';
if (select count(*) from circuito.tentativas where pessoa=u)>=20 then return 'Limite de tentativas por hora atingido.';end if;
insert into circuito.tentativas(pessoa) values(u);
select f.* into c from public.cic_cafes f join circuito.placas p on p.cafe=f.id where p.token=placa and f.active;
if c.id is null then return 'Adesivo inválido.';end if;
if c.lat is null or c.lng is null or latitude is null or longitude is null or precisao is null or latitude not between -90 and 90 or longitude not between -180 and 180 or precisao not between 0 and 200 then return 'Localização sem precisão suficiente.';end if;
d:=12742000*asin(sqrt(least(1,power(sin(radians(latitude-c.lat)/2),2)+cos(radians(latitude))*cos(radians(c.lat))*power(sin(radians(longitude-c.lng)/2),2))));
if d>300+precisao then return 'Aproxime-se da cafeteria.';end if;
insert into public.cic_visitas(pessoa,cafe,metros) values(u,c.id,round(d)) on conflict do nothing;
if not found then return 'Visita já registrada.';end if;return 'Check-in confirmado!';
end$$;
create function public.cic_excluir() returns void language sql security definer set search_path='' as $$delete from auth.users where id=auth.uid()$$;
revoke all on function public.cic_checkin(uuid,double precision,double precision,double precision),public.cic_excluir() from public,anon;
grant execute on function public.cic_checkin(uuid,double precision,double precision,double precision),public.cic_excluir() to authenticated;
commit;
